To set up an ASP.NET Core API proxy that can handle requests from another endpoint, you can use a combination of middleware and a custom HTTP handler. Here's a step-by-step guide on how to achieve this:

1. **Create a new ASP.NET Core project**:
   - Open Visual Studio and create a new ASP.NET Core project.
   - Choose the "ASP.NET Core Web Application" template.

2. **Add a new middleware**:
   - In the `Startup.cs` file, add a new middleware class that will handle the proxy requests.
   - Create a new class named `ProxyMiddleware` and add the following code:

```csharp
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Routing;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace YourProjectName
{
    public class ProxyMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger<ProxyMiddleware> _logger;

        public ProxyMiddleware(RequestDelegate next, ILogger<ProxyMiddleware> logger)
        {
            _next = next;
            _logger = logger;
        }

        public async Task Invoke(HttpContext context)
        {
            // Check if the request is a proxy request
            if (context.Request.Method == "GET" && context.Request.Path.StartsWithSegments("/api"))
            {
                // Get the original request
                var originalRequest = context.Request;

                // Create a new request with the proxy endpoint
                var proxyRequest = new Request
                {
                    Method = "GET",
                    Path = "/api",
                    Headers = new Dictionary<string, string>
                    {
                        { "X-Original-Request", originalRequest.Method + " " + originalRequest.Path }
                    }
                };

                // Send the proxy request to the original request
                await _next.Invoke(proxyRequest);
            }
            else
            {
                // Call the original middleware
                await _next.Invoke(context);
            }
        }
    }
}
```

3. **Configure the middleware**:
   - In the `Startup.cs` file, add the following code to configure the middleware:

```csharp
public void Configure(IApplicationBuilder app, IHostingEnvironment env, ILoggerFactory loggerFactory)
{
    // Other middleware configurations...

    // Configure the proxy middleware
    app.UseMiddleware<ProxyMiddleware>();

    // Other middleware configurations...
}
```

